@startuml

class Faculty {
  + name : string
}

class Institute {
  + name : string
  + address : string
}

class Employee {
  + socialSecurityNumber : string
  + name : string
  + emailAddress : string
}

class AdministrativeStaff extends Employee {
}

class ResearchAssistant extends Employee {
  + fieldOfResearch : string
}

class Lecturer extends ResearchAssistant {
}

class Project {
  + name : string
  + startDate : date
  + endDate : date
}

class ProjectParticipation {
  + hours : int
}

class Course {
  + id : int
  + name : string
  + weeklyDuration : int
}

Faculty "1" *-- "1..*" Institute
Faculty "1" -- "1" Employee : headed by dean
Employee "1" -- "*" ProjectParticipation
Project "1" -- "*" ProjectParticipation
ResearchAssistant "1..*" -- "1..*" Institute : assigned to
Lecturer "1..*" -- "*" Course : teaches
ProjectParticipation "*" -- "1" ResearchAssistant

@enduml

